import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const { colors, typography } = config.visual;

  const textContent = {
    kicker: "NOVA ATELIER / JOURNAL",
    hero1: "PRECISION IS",
    hero2: "A HABIT.",
    body: "Notes from the bench: tolerances, tempering, and the case for slower watchmaking.",
    caption: "ISSUE 12 / JULY 2026"
  };

  // Helper: Convert hex to THREE.Color
  const hexToColor = (hex) => new THREE.Color(hex);

  // Helper: Create gradient texture with monochrome grain
  const createGradientTexture = (c1Hex, c2Hex, w, h) => {
    const c1 = hexToColor(c1Hex);
    const c2 = hexToColor(c2Hex);
    const data = new Uint8Array(w * h * 4);

    for (let y = 0; y < h; y++) {
      const t = y / h;
      const r = c1.r + (c2.r - c1.r) * t;
      const g = c1.g + (c2.g - c1.g) * t;
      const b = c1.b + (c2.b - c1.b) * t;

      for (let x = 0; x < w; x++) {
        const idx = (y * w + x) * 4;
        const grain = (Math.random() - 0.5) * 0.03 * 255;
        data[idx] = Math.max(0, Math.min(255, r * 255 + grain));
        data[idx + 1] = Math.max(0, Math.min(255, g * 255 + grain));
        data[idx + 2] = Math.max(0, Math.min(255, b * 255 + grain));
        data[idx + 3] = 255;
      }
    }

    const texture = new THREE.DataTexture(data, w, h, THREE.RGBAFormat, THREE.UnsignedByteType);
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearFilter;
    texture.needsUpdate = true;
    return texture;
  };

  // Create background plane with gradient + grain
  const bgGeo = new THREE.PlaneGeometry(7, 5.5);
  const bgTex = createGradientTexture(colors.background, colors.surface, 512, 320);
  const bgMat = new THREE.MeshBasicMaterial({ map: bgTex, toneMapped: false });
  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.z = -0.1;
  group.add(bgMesh);

  // Text rendering helper via ctx.fontAtlas
  const makeText = (text, typo, col) => {
    return ctx.fontAtlas.createText(text, {
      font: typo.family,
      fontSize: typo.fontSize,
      fontWeight: typo.fontWeight,
      letterSpacing: typo.letterSpacing,
      lineHeight: typo.lineHeight,
      color: col,
      toneMapped: false
    });
  };

  // Kicker text
  const kicker = makeText(textContent.kicker, typography.kicker, colors.paper);
  kicker.position.set(-3.1, 1.7, 0);
  kicker.userData.delay = 0;
  group.add(kicker);

  // Hero line 1
  const h1 = makeText(textContent.hero1, typography.hero, colors.paper);
  h1.position.set(-3.1, 0.9, 0);
  h1.userData.delay = 80;
  group.add(h1);

  // Hero line 2
  const h2 = makeText(textContent.hero2, typography.hero, colors.paper);
  h2.position.set(-3.1, 0.25, 0);
  h2.userData.delay = 160;
  group.add(h2);

  // Letterpress shadows (hero glyphs duplicated 0.02 units behind at #16161d)
  const sh1 = makeText(textContent.hero1, typography.hero, colors.ink);
  sh1.position.set(-3.1, 0.9, -0.02);
  sh1.userData.delay = 80;
  group.add(sh1);

  const sh2 = makeText(textContent.hero2, typography.hero, colors.ink);
  sh2.position.set(-3.1, 0.25, -0.02);
  sh2.userData.delay = 160;
  group.add(sh2);

  // Body paragraph
  const body = makeText(textContent.body, typography.body, colors.paper);
  body.position.set(-3.1, -0.8, 0);
  body.userData.delay = 240;
  group.add(body);

  // Caption
  const cap = makeText(textContent.caption, typography.caption, colors.accent);
  cap.position.set(-3.1, -1.9, 0);
  cap.userData.delay = 320;
  group.add(cap);

  // Accent underline rule (2.2 x 0.05 units, #ff2a38, emissive 1.2)
  const ruleGeo = new THREE.PlaneGeometry(2.2, 0.05);
  const ruleMat = new THREE.MeshBasicMaterial({
    color: hexToColor(colors.accent),
    toneMapped: false,
    emissive: hexToColor(colors.accent),
    emissiveIntensity: 1.2
  });
  const rule = new THREE.Mesh(ruleGeo, ruleMat);
  rule.position.set(-2.0, -0.15, 0);
  rule.scale.x = 0;
  group.add(rule);

  // Animate text entrance: rise-in (y +0.4 -> 0, opacity 0->1, 700ms, power3.out) with 80ms stagger
  const textObjects = [kicker, h1, h2, sh1, sh2, body, cap];

  textObjects.forEach((obj) => {
    const finalY = obj.position.y;
    obj.position.y += 0.4;

    gsap.to(obj.position, {
      y: finalY,
      delay: obj.userData.delay / 1000,
      duration: 0.7,
      ease: "power3.out"
    });
  });

  // Animate rule draw scaleX 0->1 after hero lands (860ms total)
  gsap.to(rule.scale, {
    x: 1,
    delay: 0.86,
    duration: 0.5,
    ease: "cubic-bezier(0.25, 0.46, 0.45, 0.94)"
  });

  // Cleanup
  group.userData.cleanup = () => {
    bgTex.dispose();
    bgMat.dispose();
    bgGeo.dispose();
    ruleMat.dispose();
    ruleGeo.dispose();
    gsap.killTweensOf([...textObjects.map(o => o.position), rule.scale]);
  };

  return group;
}
